// 正常字符串（无变化）
"hello".toWellFormed(); // "hello"

// 包含孤立代理码点
// \uD800 是一个高位代理，没有对应的低位代理
const badString = "abc\uD800def";
console.log(badString); // "abc" + 孤立代理 + "def"
console.log(badString.toWellFormed()); // "abc�def"

// 只有低位代理
console.log("xyz\uDC00".toWellFormed()); // "xyz�"

// 合法的代理对（不会替换）
// \uD83D\uDE00 是 😀 (U+1F600) 的代理对
"hello\uD83D\uDE00".toWellFormed(); // "hello😀"（保持不变）

// 混合情况
"ab\uD800cd\uDC00ef\uD83D\uDE00".toWellFormed(); // "ab�cd�ef😀" —— 只有孤立代理被替换

const bad = "hello\uD800world";
console.log(bad.isWellFormed()); // false

const fixed = bad.toWellFormed();
console.log(fixed); // hello�world
